// `root_element` is the block's shadow root, supplied by frappe. Leaflet
// (window.L) and its CSS both ship in frappe's core desk bundle, so no extra
// library needs loading here.
const mapEl = root_element.querySelector('#missionary-map');
if (!mapEl) {
	// bail out silently
} else {
	const FALLBACK_PHOTO = '/assets/frappe/images/default-avatar.png';

	function markerIcon(photo) {
		return L.divIcon({
			className: 'missionary-map-pin',
			html: `<img src="${photo || FALLBACK_PHOTO}" alt="" />`,
			iconSize: [50, 50],
			iconAnchor: [25, 50],
			popupAnchor: [0, -46],
		});
	}

	function popupContent(marker) {
		const el = document.createElement('div');
		el.className = 'missionary-map-popup';
		el.innerHTML = `
			<a class="missionary-map-popup-title">${frappe.utils.escape_html(marker.title)}</a>
			${marker.country ? `<div class="missionary-map-popup-country">${frappe.utils.escape_html(marker.country)}</div>` : ''}
		`;
		el.querySelector('.missionary-map-popup-title').addEventListener('click', () => {
			frappe.set_route('Form', 'Missionary', marker.name);
		});
		return el;
	}

	const map = L.map(mapEl, { scrollWheelZoom: false, worldCopyJump: true }).setView([20, 0], 2);
	const { url, options } = frappe.utils.map_defaults.tiles.default_tile;
	L.tileLayer(url, options).addTo(map);

	frappe.xcall('churchit.church_missions.doctype.missionary.missionary.get_map_markers', {}, 'GET').then((message) => {
		const markers = message || [];
		if (!markers.length) {
			mapEl.insertAdjacentHTML(
				'afterend',
				'<div class="missionary-map-empty">No missionaries have a location set yet.</div>'
			);
			return;
		}

		const points = markers.map((marker) => {
			L.marker([marker.latitude, marker.longitude], { icon: markerIcon(marker.photo) })
				.addTo(map)
				.bindPopup(popupContent(marker));
			return [marker.latitude, marker.longitude];
		});

		if (points.length > 1) {
			map.fitBounds(points, { padding: [30, 30], maxZoom: 6 });
		} else {
			map.setView(points[0], 5);
		}
	});
}

