/* Rendered inside a shadow root with desk.bundle.css linked, which already
   carries leaflet.css (see frappe/public/scss/desk.bundle.scss), so tiles and
   controls render correctly without pulling in a second copy. */
.missionary-map-card {
	padding: 4px 0;
}

.missionary-map-title {
	font-size: var(--text-lg);
	font-weight: 600;
	margin-bottom: 10px;
	color: var(--heading-color);
}

.missionary-map {
	height: 420px;
	width: 100%;
	border-radius: var(--border-radius-md);
	z-index: 1;
}

.missionary-map-empty {
	padding: 10px 2px;
	color: var(--text-muted);
	font-size: var(--text-sm);
}

/* Photo pin: a round avatar on a white disc instead of Leaflet's default
   teardrop, so the missionary's face is what reads at a glance on the map. */
.missionary-map-pin {
	display: flex;
	align-items: center;
	justify-content: center;
}

.missionary-map-pin img {
	width: 46px;
	height: 46px;
	border-radius: 50%;
	object-fit: cover;
	border: 2px solid var(--fg-color, #fff);
	box-shadow: 0 1px 4px rgba(0, 0, 0, 0.4);
	background: var(--fg-color, #fff);
}

.missionary-map-popup {
	min-width: 140px;
}

.missionary-map-popup-title {
	display: inline-block;
	font-weight: 600;
	margin-bottom: 2px;
	color: var(--link-color, var(--primary));
	cursor: pointer;
}

.missionary-map-popup-title:hover {
	text-decoration: underline;
}

.missionary-map-popup-country {
	color: var(--text-muted);
	font-size: var(--text-sm);
	margin-bottom: 6px;
}
